/** Full lyric tools for native and profile players, using the supplied picker/plasma geometry. */
public final class DevGramLyricsSheet {
 public interface Source{State current();void seek(long millis);default void start(){}default void close(){}}
 public static final class State{public final TrackQuery query;public final long position,owner;public final boolean playing;public final Bitmap cover;public final String block;public State(TrackQuery query,long position,boolean playing,Bitmap cover,long owner,String block){this.query=query;this.position=position;this.playing=playing;this.cover=cover;this.owner=owner;this.block=block;}}
 private final DevGramProfilePainter motion=new DevGramProfilePainter();
 private final BaseFragment host;private final Source source;private final int account;private final long uid;
 private final BottomSheet sheet;private final LinearLayout body;private final LyricsView lines;private final DevGramLyricsPlasma plasma;private final TextView title,artist,status,elapsed,total,generate,timecodes,wrong;private final ImageView art,plain;private final ProgressBar progress;private final ArrayList<ImageView> icons=new ArrayList<>();
 private final ArrayList<Dialog> nestedDialogs=new ArrayList<>();private DevGramLyricsPicker.Handle picker;
 private void nested(Dialog dialog){if(!allowed()){dialog.dismiss();return;}nestedDialogs.add(dialog);dialog.show();}
 private State state;private TrackQuery query;private Lyrics current,original;private JSONArray variants=new JSONArray(),pending=new JSONArray();private String key="",picked="",language="",rendered="";private int generation;private boolean closed,showSynced=true,dark,plasmaRunning,resolving;private Bitmap cover;private long lastVariants;
 private final Runnable jobs=()->{if(allowed())reload(null);};private final Runnable policy=()->{if(!allowed())sheetDismiss();};private final Runnable beat=new Runnable(){public void run(){if(!allowed()){sheetDismiss();return;}State latest=source.current();if(latest!=null&&latest.query!=null){state=latest;if(!latest.query.key().equals(key)){key=latest.query.key();query=latest.query;picked=MessagesController.getGlobalMainSettings().getString("devgramLyricsSource_"+Utilities.MD5(key),"");language=MessagesController.getGlobalMainSettings().getString("devgramLyricsLanguage","");current=original=null;rendered="";title.setText(query.title());artist.setText(query.artist()==null?"":query.artist());for(ImageView icon:icons){icon.setEnabled(true);icon.setAlpha(1f);}reload(null);}if(cover!=latest.cover){cover=latest.cover;artwork();plasma.learn(cover,dark);}lines.setPosition(latest.position,latest.playing);elapsed.setText(DevGramPlaybackState.clock(latest.position));total.setText(DevGramPlaybackState.clock(query.duration()*1000L));progress.setProgress(query.duration()>0?(int)Math.min(1000,latest.position/Math.max(1,query.duration())):0);boolean animate=latest.playing&&motion.motion()&&body.hasWindowFocus()&&DevGramProfilePolicy.allowed(uid,"music.lyrics.animated")&&!DevGramCustomizationMemory.tight();if(animate!=plasmaRunning){plasmaRunning=animate;if(animate)plasma.start();else plasma.stop();}}else{if(plasmaRunning){plasmaRunning=false;plasma.stop();}if(state!=null)lines.setPosition(state.position,false);}
  if(dark!=Theme.isCurrentThemeDark())colors();if(SystemClock.elapsedRealtime()-lastVariants>30000&&query!=null&&PlayerConfig.getLyricsOnline())fetchVariants(generation,null);body.postDelayed(this,250);}};
 private String t(String value){return DevGramLocale.text(value);}private int dp(float value){return AndroidUtilities.dp(value);}private boolean allowed(){return !closed&&host.getCurrentAccount()==account&&host.getUserConfig().getClientUserId()==uid&&DevGramProfileCustomization.enabled()&&DevGramProfilePolicy.allowed(uid,"music.lyrics");}
 public static void show(BaseFragment host,Source source){if(host.getParentActivity()!=null&&DevGramProfileCustomization.enabled()&&DevGramAppearanceAccess.check(host,"music.lyrics"))new DevGramLyricsSheet(host,source);}
 public static void showNative(BaseFragment host){show(host,new Source(){public State current(){MessageObject message=MediaController.getInstance().getPlayingMessageObject();TrackQuery query=TrackQuery.forMessage(message);if(query==null)return null;org.telegram.messenger.audioinfo.AudioInfo info=PlayerCovers.getPlayingAudioInfo(message);long position=MediaController.getInstance().getProgressMs(message);if(position<0)position=message.audioProgressMs>0?message.audioProgressMs:(long)(message.audioProgress*message.getDuration()*1000);return new State(query,position,!MediaController.getInstance().isMessagePaused(),info==null?null:info.getCover(),0,"");}public void seek(long millis){MessageObject message=MediaController.getInstance().getPlayingMessageObject();if(message!=null)MediaController.getInstance().seekToProgressMs(message,millis);}});}
 private DevGramLyricsSheet(BaseFragment host,Source source){this.host=host;this.source=source;account=host.getCurrentAccount();uid=host.getUserConfig().getClientUserId();FrameLayout root=new FrameLayout(host.getParentActivity()){
  @Override protected void onMeasure(int width,int height){int available=MeasureSpec.getSize(height);int target=Math.max(dp(320),Math.round(AndroidUtilities.displaySize.y*.66f));if(MeasureSpec.getMode(height)!=MeasureSpec.UNSPECIFIED)target=Math.min(target,available);super.onMeasure(width,MeasureSpec.makeMeasureSpec(target,MeasureSpec.EXACTLY));}
 };plasma=new DevGramLyricsPlasma(root.getContext());root.addView(plasma,new FrameLayout.LayoutParams(-1,-1));body=DevGramStudioControls.column(root.getContext());root.addView(body,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout header=new LinearLayout(root.getContext());header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(16),dp(8),dp(12),dp(8));art=new ImageView(root.getContext());art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setImageResource(R.drawable.bot_music);art.setClipToOutline(true);art.setOutlineProvider(new android.view.ViewOutlineProvider(){public void getOutline(View v,android.graphics.Outline o){o.setRoundRect(0,0,v.getWidth(),v.getHeight(),dp(12));}});header.addView(art,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout names=DevGramStudioControls.column(root.getContext());title=text("",16,true);artist=text("",13,false);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.MARQUEE);title.setMarqueeRepeatLimit(-1);title.setSelected(true);artist.setSingleLine(true);artist.setEllipsize(android.text.TextUtils.TruncateAt.END);names.addView(title);names.addView(artist);LinearLayout.LayoutParams nameLayout=new LinearLayout.LayoutParams(0,-2,1);nameLayout.setMargins(dp(10),0,dp(6),0);header.addView(names,nameLayout);LinearLayout pill=new LinearLayout(root.getContext());pill.setGravity(Gravity.CENTER);pill.setBackground(Theme.createRoundRectDrawable(dp(12),0x1cffffff));pill.addView(icon(R.drawable.msg_translate,"Язык текста",this::chooseLanguage));ImageView sourceButton=icon(R.drawable.msg_language,"Источник текста",this::chooseSource);sourceButton.setOnLongClickListener(v->{tasks();return true;});pill.addView(sourceButton);plain=icon(R.drawable.msg_photo_text_framed3,"Обычный текст",()->{showSynced=!showSynced;rendered="";render();});pill.addView(plain);pill.addView(icon(R.drawable.ic_close_white,"Закрыть",this::sheetDismiss));header.addView(pill,new LinearLayout.LayoutParams(-2,-2));body.addView(header,new LinearLayout.LayoutParams(-1,dp(64)));
  progress=new ProgressBar(root.getContext(),null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);body.addView(progress,LayoutHelper.createLinear(-1,2,18,0,18,0));LinearLayout times=new LinearLayout(root.getContext());elapsed=text("0:00",11,false);total=text("0:00",11,false);total.setGravity(Gravity.RIGHT);times.addView(elapsed,new LinearLayout.LayoutParams(0,-2,1));times.addView(total);body.addView(times,LayoutHelper.createLinear(-1,-2,18,3,18,0));
  lines=new LyricsView(root.getContext(),host.getResourceProvider());lines.setReferenceTypography(true);lines.setProgressMode(PlayerConfig.getLyricsProgress());lines.setDelegate(new LyricsView.Delegate(){public void onSeekTo(long millis){source.seek(millis);}public void onConsent(){PlayerConfig.setLyricsOnline(true);reload(null);}public void onRetry(){reload(null);}});body.addView(lines,new LinearLayout.LayoutParams(-1,0,1));status=text("",12,false);status.setGravity(Gravity.CENTER);status.setPadding(dp(16),dp(6),dp(16),dp(6));status.setOnClickListener(v->tasks());body.addView(status);
  LinearLayout actions=new LinearLayout(root.getContext());actions.setPadding(dp(18),0,dp(18),dp(14));generate=action("Запросить генерацию",()->queue("transcribe",""));timecodes=action("Генерация тайм-кодов",()->queue("timecodes",""));wrong=action("Текст не тот",()->queue("transcribe",""));actions.addView(generate,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams timeLayout=new LinearLayout.LayoutParams(0,-2,1);timeLayout.setMarginEnd(dp(8));actions.addView(timecodes,timeLayout);actions.addView(wrong,new LinearLayout.LayoutParams(0,-2,1));body.addView(actions);
  sheet=new BottomSheet.Builder(root.getContext(),false,host.getResourceProvider()).setCustomView(root).create();sheet.fixNavigationBarKey(Theme.key_dialogBackground);colors();emptyTrack();DevGramProfilePolicy.listen(policy);DevGramLyricsJobs.listen(jobs);host.showDialog(sheet,d->{closed=true;generation++;source.close();if(picker!=null)picker.dismiss();for(Dialog dialog:new ArrayList<>(nestedDialogs))dialog.dismiss();nestedDialogs.clear();body.removeCallbacks(beat);plasma.stop();DevGramProfilePolicy.unlisten(policy);DevGramLyricsJobs.unlisten(jobs);});source.start();body.post(beat);DevGramLyricsJobs.resume(account);
 }
 private void emptyTrack(){title.setText(t("Текст песни"));artist.setText(t("Данные трека пока недоступны"));lines.setState(4,t("Данные трека пока недоступны"),t("Не удалось получить текущий трек из плеера. Окно обновится, когда появятся данные."),null);generate.setVisibility(View.GONE);timecodes.setVisibility(View.GONE);wrong.setVisibility(View.GONE);plain.setVisibility(View.GONE);for(ImageView icon:icons)if(icon!=icons.get(icons.size()-1)){icon.setEnabled(false);icon.setAlpha(.4f);}}
 private void artwork(){boolean available=cover!=null&&!cover.isRecycled();art.setScaleType(available?ImageView.ScaleType.CENTER_CROP:ImageView.ScaleType.CENTER_INSIDE);int inset=available?0:dp(12);art.setPadding(inset,inset,inset,inset);if(available){art.clearColorFilter();art.setImageBitmap(cover);}else{art.setImageResource(R.drawable.bot_music);art.setColorFilter(dark?0x99ffffff:0x89111111);}}
 private TextView text(String value,int size,boolean bold){return DevGramStudioControls.text(host.getParentActivity(),value,size,bold,host.getResourceProvider());}
 private TextView action(String label,Runnable click){TextView view=text(label,13,true);view.setGravity(Gravity.CENTER);view.setPadding(dp(12),dp(10),dp(12),dp(10));view.setOnClickListener(v->click.run());ScaleStateListAnimator.apply(view);return view;}
 private ImageView icon(int drawable,String label,Runnable click){ImageView view=new ImageView(host.getParentActivity());view.setImageResource(drawable);view.setScaleType(ImageView.ScaleType.CENTER);view.setPadding(dp(9),dp(9),dp(9),dp(9));view.setContentDescription(t(label));view.setOnClickListener(v->click.run());view.setLayoutParams(new LinearLayout.LayoutParams(dp(40),dp(40)));icons.add(view);return view;}
 private void colors(){dark=Theme.isCurrentThemeDark();int ink=dark?Color.WHITE:0xff111111,dim=dark?0x99ffffff:0x89111111;body.setBackgroundColor(dark?0x66121620:0x66f4f4f6);for(TextView view:new TextView[]{title,elapsed,total,generate,timecodes,wrong})view.setTextColor(ink);artist.setTextColor(dim);status.setTextColor(dim);for(ImageView view:icons)view.setColorFilter(ink);for(TextView view:new TextView[]{generate,timecodes,wrong})view.setBackground(Theme.createSimpleSelectorRoundRectDrawable(dp(14),(ink&0xffffff)|0x24000000,(ink&0xffffff)|0x44000000));lines.setColors(ink,dim,ink,dark?Color.BLACK:Color.WHITE);artwork();plasma.learn(cover,dark);}
 private void sheetDismiss(){sheet.dismiss();}
 private void reload(DevGramLyricsPicker.Handle handle){if(!allowed()||query==null){if(handle!=null)handle.finish(false);return;}final int version=++generation;original=null;lastVariants=SystemClock.elapsedRealtime();if(current==null)lines.setState(2,null,null,null);status.setText(t("Загрузка…"));
  if(!PlayerConfig.getLyricsOnline()){MessageObject message=MediaController.getInstance().getPlayingMessageObject();TrackQuery nativeQuery=TrackQuery.forMessage(message);Lyrics embedded=nativeQuery!=null&&nativeQuery.key().equals(query.key())?LyricsRepository.fromTags(message):null;if(embedded!=null){original=current=embedded;render();}else lines.setState(1,t("Искать текст песни в интернете?"),t("Название и исполнитель будут переданы выбранному источнику текста."),t("Искать"));status.setText("");if(handle!=null)handle.finish(embedded!=null);return;}
  fetchVariants(version,handle);if(picked.equals("ai")){original=null;return;}if(picked.equals("tags")){MessageObject nativeMessage=MediaController.getInstance().getPlayingMessageObject();TrackQuery actual=TrackQuery.forMessage(nativeMessage);original=actual!=null&&TrackQuery.normalize(actual.title()).equals(TrackQuery.normalize(query.title()))?LyricsRepository.fromTags(nativeMessage):null;render();return;}
  LyricsRepository.fetchSource(query,picked,(result,error)->{if(!allowed()||version!=generation)return;original=result;render();if(handle!=null)handle.finish(result!=null);});
 }
 private void fetchVariants(int version,DevGramLyricsPicker.Handle handle){lastVariants=SystemClock.elapsedRealtime();DevGramLyricsJobs.variants(query,(data,error)->{if(!allowed()||version!=generation)return;if(data!=null){variants=data.optJSONArray("variants");pending=data.optJSONArray("pending");if(variants==null)variants=new JSONArray();if(pending==null)pending=new JSONArray();}render();if(handle!=null&&picked.equals("ai"))handle.finish(current!=null);});}
 private void render(){if(!allowed())return;Lyrics selected=original;String credit=selected==null?"":selected.provider;
  if(!language.isEmpty()||picked.equals("ai")||picked.isEmpty())for(int i=0;i<variants.length();i++){JSONObject value=variants.optJSONObject(i);if(value!=null&&value.optString("lang").equals(language)){selected=Lyrics.parse(value.optString("body"),1,t("ИИ")+(language.isEmpty()?"":" · "+value.optString("language")));credit=selected==null?"":selected.provider;break;}}
  current=selected;generate.setVisibility(current==null?View.VISIBLE:View.GONE);timecodes.setVisibility(current!=null&&!current.synced&&!current.instrumental?View.VISIBLE:View.GONE);wrong.setVisibility(current!=null?View.VISIBLE:View.GONE);plain.setVisibility(current!=null&&current.synced?View.VISIBLE:View.GONE);
  if(current==null){lines.setState(4,t("Текст не найден"),t("Выберите другой источник или запросите распознавание аудио."),null);status.setText(t("Источник текста")+": "+sourceName());return;}if(current.instrumental){lines.setState(5,t("Инструментальная композиция"),null,null);status.setText(credit);return;}
  Lyrics shown=current;if(!showSynced&&current.synced){StringBuilder body=new StringBuilder();for(Lyrics.Line line:current.lines)body.append(line.text).append('\n');shown=Lyrics.parse(body.toString(),current.source,current.provider);}String identity=(shown==null?"":shown.toText())+"\0"+credit;if(shown!=null&&!identity.equals(rendered)){rendered=identity;lines.setLyrics(shown,credit);if(state!=null)lines.setPosition(state.position,state.playing);lines.post(lines::jumpToCurrent);}status.setText(credit==null?sourceName():credit);
 }
 private String sourceName(){switch(picked){case "lrclib":return "LRCLIB";case "lrcmux":return "lrcmux / YouTube";case "netease":return "NetEase";case "tags":return t("Теги файла");case "ai":return t("ИИ");default:return t("Автоматически");}}
 private void chooseSource(){if(query==null)return;String[] values={"","lrclib","lrcmux","netease","tags","ai"};String[] names={t("Автоматически"),"LRCLIB","lrcmux / YouTube","NetEase",t("Теги файла"),t("ИИ")};int index=Arrays.asList(values).indexOf(picked);final DevGramLyricsPicker.Handle[] handle={null};picker=handle[0]=DevGramLyricsPicker.show(host.getParentActivity(),cover,dark,dark?Color.WHITE:0xff111111,t("Источник текста"),t("Сейчас")+": "+sourceName(),names,Math.max(0,index),choice->{if(!allowed())return;picked=values[choice];MessagesController.getGlobalMainSettings().edit().putString("devgramLyricsSource_"+Utilities.MD5(key),picked).apply();PlayerConfig.setLyricsOnline(true);if(handle[0]!=null)handle[0].collapse(t("Загрузка…"),0);reload(handle[0]);});}
 private void chooseLanguage(){if(query==null)return;ArrayList<String> names=new ArrayList<>(),values=new ArrayList<>();names.add(t("Оригинал"));values.add("");for(int i=0;i<variants.length();i++){JSONObject value=variants.optJSONObject(i);if(value!=null&&!value.optString("lang").isEmpty()){names.add(value.optString("language"));values.add(value.optString("lang"));}}for(int i=0;i<pending.length();i++){JSONObject value=pending.optJSONObject(i);if(value!=null&&!value.optString("lang").isEmpty()&&!values.contains(value.optString("lang"))){names.add(value.optString("language")+" · "+t("Готовится…"));values.add("pending:"+value.optString("lang"));}}names.add(t("Попросить ИИ другой язык…"));values.add("ask");final DevGramLyricsPicker.Handle[] handle={null};picker=handle[0]=DevGramLyricsPicker.show(host.getParentActivity(),cover,dark,dark?Color.WHITE:0xff111111,t("Язык текста"),language.isEmpty()?t("Оригинал"):t("Перевод ИИ"),names.toArray(new String[0]),Math.max(0,values.indexOf(language)),choice->{if(!allowed())return;String value=values.get(choice);if(value.equals("ask")){handle[0].collapse(t("Открываю перевод…"),0);handle[0].finish(true);askLanguage();}else if(value.startsWith("pending:")){handle[0].collapse(t("Перевод ещё готовится — придёт уведомление"),0);handle[0].finish(true);}else{language=value;MessagesController.getGlobalMainSettings().edit().putString("devgramLyricsLanguage",language).apply();handle[0].collapse(t("Загрузка…"),0);rendered="";reload(handle[0]);}});}
 private void askLanguage(){if(current==null){Toast.makeText(body.getContext(),t("Сначала загрузите или распознайте оригинальный текст."),Toast.LENGTH_LONG).show();return;}nested(DevGramLyricsPicker.ask(host.getParentActivity(),cover,dark,dark?Color.WHITE:0xff111111,t("Попросить ИИ перевод"),t("Готовый перевод появится в списке языков у всех. Уведомление придёт в DevGram."),t("Какой язык? Например: украинский, латиницей"),new String[0],0,t("Перевести"),(answer,choice)->queue("translate",answer)));}
 private void queue(String kind,String language){if(!allowed()||query==null||resolving||!DevGramAppearanceAccess.check(host,"profile.assistant",body))return;if(!DevGramAiClient.isConfigured()){sheet.dismiss();host.presentFragment(new DevGramAiServicesActivity());return;}if(!kind.equals("transcribe")&&current==null)return;Lyrics sourceText=kind.equals("translate")&&original!=null?original:current;String lyrics=sourceText==null?"":sourceText.toText();if(kind.equals("translate")){submit(kind,language,lyrics,null);return;}
  nested(new AlertDialog.Builder(host.getParentActivity(),host.getResourceProvider()).setTitle(t(kind.equals("timecodes")?"Генерация тайм-кодов":"Распознать текст песни?")).setMessage(t("Аудио текущего трека будет передано выбранному сервису ИИ. Нужна модель с поддержкой аудио. Результат появится у всех пользователей, а задача продолжится после закрытия этого окна.")).setPositiveButton(t("Продолжить"),(dialog,which)->{if(!allowed())return;resolving=true;TrackQuery requested=query;State playing=state;status.setText(t("Подготавливаю аудио…"));DevGramLyricsAudioSource.resolve(account,requested,playing==null?0:playing.owner,playing==null?"":playing.block,file->{resolving=false;if(!allowed()||!query.key().equals(requested.key())){if(file!=null&&file.getParentFile().equals(new File(ApplicationLoader.applicationContext.getCacheDir(),"devgram-lyrics-audio")))file.delete();return;}if(file==null){status.setText(t("Полный аудиотрек недоступен. Загрузите его в плеере Telegram или проверьте доступ музыкального сервиса."));return;}submit(kind,language,lyrics,file);});}).setNegativeButton(t("Отмена"),null).create());
 }
 private void submit(String kind,String language,String lyrics,File audio){DevGramLyricsJobs.submit(account,query,kind,language,lyrics,audio,(data,error)->{if(!allowed())return;if(data==null){status.setText(t("Не удалось добавить задачу"));return;}JSONObject job=data.optJSONObject("job");if(job!=null&&kind.equals("translate"))this.language=job.optString("lang");status.setText(t("Задача в очереди. Уведомление появится в DevGram."));fetchVariants(generation,null);});}
 private void tasks(){if(!allowed())return;DevGramLyricsJobs.list(account,(data,error)->{if(!allowed())return;LinearLayout content=DevGramStudioControls.column(body.getContext());content.setPadding(dp(18),dp(8),dp(18),dp(20));JSONArray jobs=data==null?null:data.optJSONArray("jobs");if(jobs==null||jobs.length()==0)content.addView(text(data==null?"Не удалось загрузить задачи":"Задач пока нет",15,false));else for(int i=0;i<jobs.length();i++){JSONObject job=jobs.optJSONObject(i);if(job==null)continue;String state=job.optString("state"),label=t(state.equals("queued")?"В очереди":state.equals("running")?"Обрабатывается…":state.equals("complete")?"Готово":state.equals("cancelled")?"Отменено":"Ошибка обработки");TextView row=text("",14,false);if(state.equals("failed"))row.setOnClickListener(v->{if(!allowed())return;nested(new AlertDialog.Builder(host.getParentActivity(),host.getResourceProvider()).setTitle(t("Ошибка обработки")).setMessage(t(job.optString("error").equals("audio_model_required")?"Выбранная модель ИИ не поддерживает аудио. Выберите совместимую модель в настройках сервиса.":job.optString("error").equals("invalid_lyrics")?"Сервис вернул текст с некорректными тайм-кодами. Можно повторить запрос или сменить модель.":"Сервис ИИ не смог обработать трек. Проверьте подключение и настройки сервиса.")).setPositiveButton(t("Настроить сервис ИИ"),(d,w)->{sheet.dismiss();host.presentFragment(new DevGramAiServicesActivity());}).setNegativeButton(t("Закрыть"),null).create());});row.setText(job.optString("title")+" · "+job.optString("artist")+"\n"+label+(job.optString("language").isEmpty()?"":" · "+job.optString("language")));row.setPadding(0,dp(12),0,dp(12));if(state.equals("queued")||state.equals("running"))row.setOnClickListener(v->nested(new AlertDialog.Builder(host.getParentActivity(),host.getResourceProvider()).setTitle(t("Отменить задачу?")).setPositiveButton(t("Отменить"),(d,w)->DevGramLyricsJobs.cancel(account,job.optLong("id"),(result,failure)->{changedTasks();})).setNegativeButton(t("Продолжить"),null).create()));content.addView(row);}ScrollView scroll=new ScrollView(body.getContext());scroll.addView(content);nested(new BottomSheet.Builder(body.getContext(),true,host.getResourceProvider()).setTitle(t("Задачи ИИ")).setCustomView(scroll).create());});}
 private void changedTasks(){if(allowed())reload(null);}
}
